/**
 * @param {HTMLElement} el 마운트 지점
 * @param {Array<{
 *   numbers: number[],
 *   score: number,
 *   odd_even_ratio: string,
 *   section_distribution: number[]
 * }>} combos
 */
export function renderCardList(el, combos) {
  if (!(el instanceof HTMLElement)) return;
  el.innerHTML = "";

  if (!Array.isArray(combos) || combos.length === 0) {
    const hint = document.createElement("p");
    hint.className = "empty-hint";
    hint.textContent = "추천 결과가 없습니다.";
    el.appendChild(hint);
    return;
  }

  // 최소 구현: 번호만 출력하는 기본 리스트. 상세 시각화는 module_3에서 치환.
  const list = document.createElement("ol");
  list.className = "card-list card-list--placeholder";

  for (const combo of combos) {
    const item = document.createElement("li");
    item.className = "card-list__item";
    const numbers = Array.isArray(combo?.numbers) ? combo.numbers : [];
    item.textContent = numbers.join(" · ");
    list.appendChild(item);
  }

  el.appendChild(list);
}

