/**
 * @param {HTMLElement} el 마운트 지점
 * @param {import('../state.js').Store | {
 *   getState: () => import('../state.js').AppState,
 *   setState: (patch: Partial<import('../state.js').AppState>) => unknown,
 *   subscribe: (fn: (s: import('../state.js').AppState) => void) => () => void
 * }} store
 */
export function renderParamPanel(el, store) {
  if (!(el instanceof HTMLElement) || !store || typeof store.getState !== "function") {
    return;
  }

  el.innerHTML = "";
  el.classList.add("param-panel", "param-panel--placeholder");

  const list = document.createElement("dl");
  list.className = "param-panel__list";

  const render = () => {
    const { params } = store.getState();
    list.innerHTML = "";
    list.appendChild(makeRow("추천 조합 수 (n)", `${params.n}개`));
    list.appendChild(makeRow("분석 회차 (draws)", `${params.draws}회`));
    list.appendChild(
      makeRow("모드", params.offline ? "오프라인 캐시" : "온라인 분석"),
    );
  };

  render();
  el.appendChild(list);

  if (typeof store.subscribe === "function") {
    store.subscribe(render);
  }
}

function makeRow(label, value) {
  const wrap = document.createElement("div");
  wrap.className = "param-panel__row";
  const dt = document.createElement("dt");
  dt.className = "param-panel__label";
  dt.textContent = label;
  const dd = document.createElement("dd");
  dd.className = "param-panel__value";
  dd.textContent = value;
  wrap.append(dt, dd);
  return wrap;
}

